    id: impl Into<SharedString>,
    handle: &ScrollHandle,
    content: impl IntoElement,
    fill: bool,
    lock: Option<(bool, ToggleLock)>,
    cx: &App,
) -> AnyElement {
    let row = h_flex()
        .items_stretch()
        .w_full()
        .when(fill, |row| row.flex_1().min_h_0().h_full())
        .child(
            div()
                .flex_1()
                .min_w_0()
                .when(fill, |it| it.h_full())
                .child(content),
        )
        .child(scroll_column(id.into(), handle, lock, cx));
    row.into_any_element()
}

